mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tasks
    WHERE id = #{taskId}
)

SELECT id, user_id, title, completed
FROM tasks
WHERE id = #{taskId}
  AND user_id = #{userId}

mapper.update:
UPDATE tasks
SET title = #{title},
    completed = #{completed}
WHERE id = #{taskId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM tasks
WHERE id = #{taskId}
  AND user_id = #{userId}
